//----------------------------------------------------------------------------------------// Typedefs//----------------------------------------------------------------------------------------typedef long ControlCharSet;//----------------------------------------------------------------------------------------// TTEView: TTEView is a view subclass representing a TextEdit record. TextEdit is the// simple text-editing facility built into the Macintosh ROM. The purpose of a TEView is// to make TextEdit function properly in a MacApp environment, for things like scrolling,// printing, page breaks, and command handling//----------------------------------------------------------------------------------------class EXPORT_MA TTEView : public TView// TTEView is a view subclass representing a TextEdit record. TTEView// provides a view with the basic function of TextEdit. TextEdit// is the simple text-editing facility built into the Macintosh// ROM. The purpose of a TTEView object is to ensure proper functioning// (for instance, scrolling, printing, page breaks, and command// handling) of TextEdit in a MacApp environment.{	MA_DECLARE_CLASS;	public:	//------------------------------------------------------------------------------------	// Initialize and Free	//------------------------------------------------------------------------------------	TTEView(const CViewPoint& itsLocation = gZeroVPt,								const CViewPoint& itsSize = gZeroVPt,								SizeDeterminer itsHDeterminer = sizeVariable,								SizeDeterminer itsVDeterminer = sizeVariable,								const CViewRect& itsInset = gZeroVRect,								const CTextStyle_AC& itsTextStyle = gSystemStyle,								short itsJustification = teFlushDefault,								bool itsAutoWrap = true,								bool itsMakeTERecord = kDontMakeTERecord);		// Constructor			TTEView(const TTEView& inTEView);		// Copy Constructor	virtual ~TTEView();		// Frees the TERecord and optionally fText, then Inherited::Free.	//------------------------------------------------------------------------------------	// Standard signature support.	//------------------------------------------------------------------------------------	virtual IDType GetStandardSignature() const;	// override 		// Returns this class's standard signature.	//------------------------------------------------------------------------------------	// Stream I/O protocol support.	//------------------------------------------------------------------------------------	virtual void ReadFields(CStream_AC* aStream);	// override 		virtual void WriteFields(CStream_AC* aStream) const;	// override 	//------------------------------------------------------------------------------------	// View method overrides	//------------------------------------------------------------------------------------	virtual void MakeTERecord();		// Called with grafport properly set, to create the actual TE Record	//------------------------------------------------------------------------------------	//  Commands and Menus	//------------------------------------------------------------------------------------	virtual void DoCommandKeyEvent(TToolboxEvent* event);	// Override		// Handles non-menu command keys	virtual void DoKeyEvent(TToolboxEvent* event);		// Handles keystrokes	virtual TTECommand* DoMakeEditCommand(CommandNumber aCommandNumber);		// Make a command for handling edit menu stuff	virtual TTEStyleCommand* DoMakeStyleCommand(const CTextStyle_AC& aStyle,													   CommandNumber itsCommandNumber,													   short itsMode);	// Make a style change command	virtual TTETypingCommand* DoMakeTypingCommand(const CStr2_AC& ch);		// Make a typing command for handling the new character[s]	virtual void DoMenuCommand(CommandNumber aCommandNumber);		// Handles menu commands	virtual void DoMouseCommand(CViewPoint& theMouse,									   TToolboxEvent* event,									   CPoint_AC hysteresis);		// Handles mousepresses	virtual void DoneTyping();		// No further typing can occur for the current typing command	virtual void DoSetupMenus();		// Sets up menus	virtual void SetActive(bool state);		// Calls TEActivate or TEDeactivate	virtual void BecameWindowTarget();		// Override		virtual void ResignedWindowTarget();		// Override		virtual void BecameTarget();				// Override		virtual void ResignedTarget();			// Override	virtual void SetEnable(bool state);		// Resets the view's idle	virtual TEditText* GetEditText();		// Get the edit text view, if any, that owns this TE view. 	void ForgetIfTypingCommand(TTETypingCommand* typingCommand);		// Set fTypingCommand to NULL if it's the same as the specified one.		// Used to break dependency of commands on the floating TE.	//------------------------------------------------------------------------------------	//  Screen Display	//------------------------------------------------------------------------------------	virtual bool DoIdle(IdlePhase phase);		// Blinks the insertion CPoint_AC	virtual void Draw(const CViewRect& area);		// Draw the text in a frame or on the printed page	virtual void ShowReverted();		// Make sure line starts are correct before redisplay	//------------------------------------------------------------------------------------	//  Size Changes	//------------------------------------------------------------------------------------	virtual void BeInPort(GrafPtr itsPort);		// Now that a grafport is established for the view, tells TextEdit about it	virtual void BeInScroller(TScroller* itsScroller);		// Gives us a chance to set the scroll parameters	virtual CViewRect CalcMinFrame();		// Compute the minimum size of the view	virtual long CalcRealHeight();		// Calculate true height of record, including last character if it is a carriage        // return	virtual long CalcRealWidth();		// Calculate true width of record.Only supported for NON-styled TE Records right        // now	virtual void ComputeFrame(CViewRect& newFrame);		// Compute the actual size of the view	virtual void SetFrame(const CViewRect& newFrame, bool invalidate);		// Installs the new size for both the View and TextEdit	virtual void UpdateCoordinates() const;		// Keeps the TE in synch with any VSpace or QDSpace origin changes.	virtual void SynchView(bool redraw);		// Keeps view metrics in synch after TextEdit operation. If redraw is true then        // ScrollSelectionIntoView is called to make sure the selection is visible.	virtual CViewPoint OffsetToPt(short offset);		// Converts offset in text to view coordinates.	virtual short OffsetToLine(short offset);		// Returns the line number that contains the offset	virtual short OffsetToLineStart(short offset);		// Returns the offset of the start of the line that contains the offset	virtual short OffsetToLineEnd(short offset);		// Returns the offset of the end of the line that contains the offset	virtual short PtToOffset(const CViewPoint& aPoint);		// Converts a view CPoint_AC to an offset in the text.	virtual bool WordBounds(short charPos,									  short& wordStart,									  short& wordEnd);		// charPos is the offset of a specific character in the text Returns: true iff        // that character is part of a word wordStart = offset of first character of the        // word wordEnd= offset of final character of the word Note: these are CHARACTER        // offsets, not CURSOR POSITIONS.	//------------------------------------------------------------------------------------	// NOTE -- These methods apply only to a TEView installed as the view in the Clipboard	//------------------------------------------------------------------------------------	virtual bool ContainsClipType(ResType aType);		// Determines whether the indicated clipboard type can be produced by the view	virtual long GivePasteData(Handle aDataHandle,									  ResType dataType);		// Supplies data to be PASTED by some requesting PASTE command	virtual void WriteToDeskScrap();		// Produces TEXT data for the Desk Scrap when called upon to do so	//------------------------------------------------------------------------------------	//  Miscellaneous	//------------------------------------------------------------------------------------	virtual void AutoScrolling(bool doScrolling);		// Set TERecord auto scrolling to given value via TEAutoScroll	virtual bool ClickLoop();		// Forwarded to from the global routine: ClickLoopForTTEView which was set as the        // TE's ClickLoop.Typically handles autoscrolling for the view.	virtual void CalcSelLoc(CViewRect& selectionRect);		// Calculates the location of the current Selection	virtual void SetSelection(short NewSelStart,									 short NewSelEnd,									 bool redraw);	virtual void GetSelectionString(CStr255_AC& selection);		// Returns the selected text as a CStr255_AC. If the selection is longer than 255        // characters, the first 255 characters are returned			virtual bool WantsToBeTarget()		// We want to be target only if we're enabled.		{ return TView::WantsToBeTarget() && IsEnabled(); }			virtual short GetNumberOfChars();		// Returns the number of characters stored in the text handle in a script		// manager compatible way.	short GetCharacterOffset(short fromOffset);		// Returns the offset of the beginning of the proposed offset		// Correcting for multibyte characters	short GetBytesInCharacter(short atOffset);		// Returns the number of bytes in the character pointed	short GetNextCharacterOffset(short fromOffset);		// Returns the offset of the character following this offset		// Correcting for multibyte characters	short GetPrevCharacterOffset(short fromOffset);		// Returns the offset of the character before this offset		// Correcting for multibyte characters	virtual void ChangeWrap(bool newAutoWrap,								   bool redraw);		// Changes auto-wrapping behavior, redrawing if requested	virtual bool ContinuousStyle(short firstChar,										   short lastChar,										   short& mode,										   CTextStyle_AC& aStyle);		// Returns true if the style of the characters within the given range is wholly        // continuous. The style attributes to check are specified by mode, which has the        // same meaning as in the TextEdit call TESetStyle. Attributes which are        // continuous are returned in aStyle, with the appropriate bits set in mode. Font        // style attribute bits are individually checked across the selection range, and        // returned set to 1 if that attribute is continuous.	virtual short OffsetToScript(short offset);		// returns the script code in effect at the given offet	virtual void ExtractStyles(TEStyleHandle& theStyles,									  STHandle& theElements) const;		// Extract handles to style information for a TextEdit record, presumably for the        // purpose of storing the data to disk. Note that line heights can be        // recalculated, and as such don't need to be stored.	virtual Handle ExtractText() const;		// For sake of completeness. Extract handle to text, presumably for the purpose of        // storing the text externally (perhaps to disk).	virtual void RecalcText();		// Tells TextEdit to recompute linestarts	virtual void ScrollSelectionIntoView(bool redraw);	// Override		// Scrolls the selection into view -- called after Commands are done or undone If        // auto scrolling is on, calls TESelView to do the right thing	virtual void SetJustification(short newJust,										 bool redraw);		// Sets the TERecord to the given justification. If redraw is true then the view        // is redrawn by calling ForceRedraw. Otherwise it is assumed the called will get        // the view redrawn.	virtual void SetOneStyle(short theStart,									short theEnd,									short theMode,									const CTextStyle_AC& theStyle,									bool redraw);		// Sets a text style continuously over a range. In unstylish TERecords, the style        // is set across the entire record. If redraw is true then the text is redrawn.	virtual void SetText(const CStr255_AC& theText);		// Convenience routine, to save from having to create a handle just to pass to        // StuffText. Note that if fSavedTEHandle already holds a saved handle, it will be        // disposed before StuffText is called.	virtual bool SpaceForStyles(long rangeStart,										  long rangeEnd);		// Returns true if there is enough memory to hold the styles over the given range        // in the TERecord	virtual void StuffStyles(TEStyleHandle theStyles,									STHandle theElements);		// Installs style information, presumably fetched from disk, into the TextEdit        // record.	virtual void StuffText(Handle theText);		// Installs text into the TextEdit record. Note that this destroys any existing        // style information -- StuffStyles should be called if styles are to be attached        // to this text information	virtual void StyleInsert(const void *text, long length, StScrpHandle hST);		// Use in place of TEStyleInsert. Ensures that the text is inserted with the proper		// keyscript for international text.	virtual void StuffTERects(const CRect_AC& newTERect);		// installs "newTERect" as the dest & view CRect_AC of the TextEdit record	inline unsigned short GetMaxLength() { return fMaxChars; }	void SetMaxLength(unsigned short newMaxLength) { fMaxChars = newMaxLength; }	//------------------------------------------------------------------------------------	//  Printing	//------------------------------------------------------------------------------------	virtual ViewCoordinate DoBreakFollowing(VHSelect vhs,												ViewCoordinate previousBreak,												bool& automatic);		// Computes the next page-break following 'previousBreak' in direction given by        // 'vhs'	virtual CViewPoint DoCalcViewPerPage();		// Computes how much of the view is to be allocated to each printed page	virtual void DoSetPageOffset(const CViewPoint& coord);		// At printing time, determine the location of the 'interior' (body) of the page	virtual CViewRect GetPrintExtent();		// Print extent is the view's extent minus the insets.#if qDrag	//------------------------------------------------------------------------------------	//  Drag/Drop Support	//------------------------------------------------------------------------------------		virtual RgnHandle DoMakeDragCursorRegion(); // Override		// Create and return a description of the drag region in local coordinates			virtual bool WillDrag(const CViewPoint& theMouse, const RgnHandle dragCursorRegion); // Override		// Give a mouse point in local coordinates, returns true if clicking the mouse		// would initiate a drag operation		virtual short GetWillDragCursorID();	// Override		// display quickdraw arrow cursor			virtual short GetIsDraggingCursorID();	// Override		// display quickdraw arrow cursor	virtual void DoAddDragContent(); // Override		// Install flavors into the current drag operation	virtual bool WillAcceptDrop(CDragItemIterator& dragItemIterator); // Override		// Return true if the drag contains exactly one item and is available as		// text			virtual TDragTracker* DoMakeDragTracker(CommandNumber itsCommandNumber,											const CViewPoint& itsMouse = gZeroVPt,											const TToolboxEvent* event = NULL);  // override		// Return a tracker for tracking a drag within the view. 		#endif // qDrag//----------------------------------------------------------------------------------------// static member functions//----------------------------------------------------------------------------------------public:	static void SetSelect(short theStart, short theEnd, TEHandle hTE);		// For those times when we don't want the selection range hilited when changed#if q68K	static pascal Boolean ClickLoopForTTEView();#elif !qMSWindows	static pascal Boolean ClickLoopForTTEView(TEPtr pTE);#endif		// Called from TextEdit when the mouse is down forwards to TTEView::ClickLoop so that	    // autoscrolling may be done.		// NOTE: this routine requires the pascal keyword because the Toolbox requires it	#if qDebug	static void DumpTERecord(TEHandle aTEH);		// writes salient information about the TERecord out to the Debug window#endif			static short TEIsFrontOfLine(short offset, TEHandle theTE);		static short TEGetLine(short offset, TEHandle theTE);		static bool IsBlank( Handle theText, short offset, short& length, short inScript = smCurrentScript );protected:#if qDebug	static void WriteChar(short index, Handle hText);#endif	//----------------------------------------------------------------------------------------// data members//----------------------------------------------------------------------------------------public:	CTextStyle_AC fTextStyle;						// Current style of text	CViewRect fInset;								// Amount to inset text from edges of view	TTETypingCommand* fTypingCommand;			// The current TE Typing command relating                                                // to me, if any	TEHandle fHTE;								// Handle to the actual TextEdit object	Handle fText;								// The text in the TEHandle	Handle fSavedTEHandle;						// Saved handle from TENew	ViewCoordinate fLastHeight;					// Last checked height of record. If the                                                // record is stylish, this represents the                                                // height in pixels. For old-style                                                // records, equals number of lines.	ViewCoordinate fLastWidth;						// Last checked width of record. Not                                                // currently used If the TE is styled,                                                // this represents the width in pixels.	ViewCoordinate fMinAhead;						// Minimum amount by which to autoscroll                                                // ahead when scrolling selection into                                                // view.(When typing etc.	ViewCoordinate fLastPageBreak;					// Caches last page break computed.	CommandNumber fKeyCommandNumber;			// Will be used as the CPascalStr_AC number for                                                // "Undo Typing"	ControlCharSet fControlChars;				// Control chars accepted in text	ResNumber fTextStyleRsrcID;					// Rsrc ID of 'TxSt' resource which has                                                // CTextStyle_AC information.	short fJustification;						// Current justification of text record	unsigned short fLastLine;					// Last line of text of the last page                                                // break	short fSelAnchor;							// current selection "anchor"	short fUpDownH;								// for repeated Up- and/or Down-arrowing		bool fPreferOutline;						// prefer outline fonts?	bool fAcceptsChanges;						// Set to false to have text which will                                                // not accept any change, such as text on                                                // the Clipboard, or perhaps received mail	bool fAutoWrap;								// Set to false for line wrapping at CR's                                                // only	bool fFreeText;								// Determines if fText should be freed on                                                // Free.	bool fUpDown;								// used to keep track of horizontal                                                // positionprotected:	unsigned short fMaxChars;					// Maximum number of chars to accept into                                                // fText. Default is SHRT_MAX; stuff to                                                // different value if you want to limit                                                // max chars to fewer than SHRT_MAX//----------------------------------------------------------------------------------------// static data members//----------------------------------------------------------------------------------------public:	static TEClickLoopUPP fgDefClickLoopProc;				// Standard TextEdit click loop routine		// The following are considered private, but appear in the interface in case you need to	// override a method that uses one of these.	static TTEView* fgCurrTEView;							//For the benefit of ClickLoopForTTEView only		static TEClickLoopUPP fgClickLoopProc;		// The fgClickLoopProc global is used for PPC compatibility.  In the case of a		// PPC application, we create a single UniversalProcPtr for ClickLoopForTTEView.	#if qDebug	static bool fgTEIntenseDebugging;	#endif};//----------------------------------------------------------------------------------------// Global procedure declarations//----------------------------------------------------------------------------------------EXPORT_MA void InitUTEView();	// Initialize TEView unit.#endif // __UTEVIEW__/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/21/96	[1117870] (2-BYTE) TTEView and Left&Right Arrow							[1115111] (2-BYTE) TTEView::GetNumberOfChars returns 0 after 1 character has been typed							[1353017] (Double-byte) Second Character Lost		 5/24/96	[1285227] TTEView::ExtractStyles needs to be const		 5/08/96	Cleanup CRGBColor_AC and add new class CTextStyle_AC		04/26/96	Removed override of InvalidateFrameDifference which was causing an improper							invalidation. (Not the view's extent)		----- R10 -----		03/28/96	CalcMinFrame now returns a CViewRect		03/28/96	DoCalcViewPerPage/GetPrintExtent changed to return VPoints/VRects		03/26/96	Condition DumpTERec calls under qDebug		03/25/96	TToolboxEvent::fCharacter is obsolete							Made empty UAdorners constructors inline		03/24/96	[1117870] (2-Byte) TTEView and Left&Right Arrow.							Added TTEView::GetCharacterOffset/GetBytesInCharacter/GetNextCharacterOffset							/GetPrevCharacterOffset.							Removed '', changed all occurrances of (**foo). to (*foo)->							Ran thru C++ formatter. Changed pCurrTEView to fgCurrTEView							Changed pClickLoopProc to fgClickLoopProc. Changed							gDefClickLoopProc to fgDefClickLoopProc. Changed							pTEIntenseDebugging to fgTEIntenseDebugging		 3/24/96	TTEView::OffsetToPt returns CViewPoint now		 3/01/96	Re-arranged data members, natural alignment results in 		 					reduced storage size.							Grouped some globals and global functions as static members.		12/20/95	Add GetEditText. 		10/20/95	TTEView overrides GetWillDragCursorID and GetIsDraggingCursorID.		10/20/95	Add fHiliteRgn member for tracking selection rgn during drag.							Conditionalize definition of drag-related data.		10/10/95	Change type of gDefClickLoopProc from ProcPtr to TEClickLoopUPP.		----- 3.3b1 -----		  7/5/95	Cosmetic. 		  4/8/95	Use size limits from limits.h instead of MacAppTypes. 		 3/30/95	Change DragEnter to DoDragEnter.		 					Change DragWithin to DoDragWithin.		 					Change DragLeave to DoDragLeave.		 					Change AddDragContent to DoAddDragContent.		 					Change FulfillPromise to DoFulfillPromise.		 					Change MakeDragDropCommand to DoMakeDragDropCommand.		 					Change MakeDragCursorRegion to DoMakeDragCursorRegion.		 3/28/95	Change MakeDragTestRegion to MakeDragCursorRegion.		 					Add dragCursorRegion param to WillDrag.		 3/15/95	Drag and drop face lift.		 3/13/95	Change Free methods to destructors. 		  3/5/95	Support MakeDragDropCommand.		 2/23/95	Split ReceiveDrop into ReceiveDropCopy and ReceiveDropMove.		 2/19/95	Make parameter to WantsToDrag const. 		  2/6/95	Add the following to TTEView to support drag:							WantsToDrag, GetDragRegion, DoAddDragFlavors,							SendDragData.			----- 3.5d3 Release -----		11/11/94	Conditionally compile in drag support if qDrag is true.		 9/23/94	Made TTEView::ExtractText const per David Gradwell's							request.		  9/9/94	Added global routines: TEIsFrontOfLine,							TEGetLine, IsBlank and TTEView::DragFeedback and							TTEView::DrawCaret per Eric Hanig's Drag and Drop							additions.*/